let titleSort='Featured',channelSort='Playlist order',sportsSort='Schedule';
const titleSorts=['Featured','Most popular','Top rated','Newest','Oldest','A–Z','Z–A'];
function sortedTitles(items){return [...items].sort((a,b)=>titleSort==='Most popular'?(b.popularity||0)-(a.popularity||0):titleSort==='Top rated'?(b.rating||0)-(a.rating||0):titleSort==='Newest'?(b.date||'').localeCompare(a.date||''):titleSort==='Oldest'?(a.date||'9999').localeCompare(b.date||'9999'):titleSort==='A–Z'?a.title.localeCompare(b.title):titleSort==='Z–A'?b.title.localeCompare(a.title):0);}
function sortTools(kind,value,options,note=''){return '<label class="sort-tools">Sort <select data-sort="'+kind+'">'+options.map(v=>'<option '+(v===value?'selected':'')+'>'+escape(v)+'</option>').join('')+'</select><small>'+note+'</small></label>';}
document.addEventListener('change',event=>{const kind=event.target.dataset.sort;if(!kind)return;const value=event.target.value;if(kind==='titles'){titleSort=value;if(category==='Library')renderLibrary();else reorderTitles();}if(kind==='channels'){channelSort=value;renderPlaylist();}if(kind==='sports'){sportsSort=value;renderSports();}});
function reorderTitles(){const grid=$('#catalog-grid');if(!grid)return;const items=[...loadedKeys].map(id=>titles.get(id)).filter(Boolean);grid.innerHTML=sortedTitles(items).map(item=>card(item)).join('');}
const sources=[['vidstuck','VidStuck'],['embedwave','Embedwave (BETA)'],['vidsrc-sh','VidSrc.sh'],['rawcast','RawCast · Limited quota']];
function sourceOverrides(){try{return JSON.parse(localStorage.getItem('zero-title-sources')||'{}')||{};}catch{return {};}}
function playbackSourceValid(id){return sources.some(([sourceId])=>sourceId===id);}
function sourceFor(item){const global=state?.settings?.source;if(!item)return playbackSourceValid(global)?global:'vidstuck';const once=oneTimeSources.get(key(item));if(playbackSourceValid(once))return once;const saved=sourceOverrides()[key(item)];if(playbackSourceValid(saved))return saved;return playbackSourceValid(global)?global:'vidstuck';}
function sourceName(id){return sources.find(x=>x[0]===id)?.[1]||'VidStuck';}
function sourceLabel(item){const id=sourceFor(item);return sourceName(id)+(id==='vidstuck'?' · Recommended':'');}
function sourceButton(item){return `<button data-action="source">${escape(sourceLabel(item))} ▾</button>`;}
function atmosphere(item){const img=$('#ui-atmosphere img');if(item?.backdrop&&img.getAttribute('src')!==item.backdrop)img.src=item.backdrop;}
function ensureSourceConfirm(){let dialog=$('#source-confirm');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='source-confirm';dialog.innerHTML='<div class="settings-body"><span class="eyebrow">THIS TITLE ONLY</span><h2 id="source-confirm-title">Keep source?</h2><p id="source-confirm-copy"></p><div class="actions"><button class="primary" data-action="source-keep">✓ Keep for this title</button><button data-action="source-once">Just this time</button><button data-action="source-cancel">Cancel</button></div></div>';document.body.appendChild(dialog);return dialog;}
function openSources(item){sourcePickerItem=item||activeDetail||heroPicks()[heroIndex];if(!sourcePickerItem)return;window.zeroExperience?.stop();const selected=sourceFor(sourcePickerItem);$('#source-options').innerHTML=sources.filter(([id])=>id!=='rawcast'||state.settings.rawcastPlayback===true).map(([id,name])=>`<button class="source-option ${selected===id?'selected':''}" data-source="${id}">${name}${id==='vidstuck'?'<small>Recommended · default for other titles</small>':id==='rawcast'?'<small>Requires your API key. Streaming uses your limited request quota.</small>':''}${selected===id?'<span>✓</span>':''}</button>`).join('');const note=$('#source-picker p');if(note)note.textContent='Choose a source for '+sourcePickerItem.title+'. Other movies and series stay on VidStuck.';$('#source-picker').showModal();}
async function surpriseMovie(){const button=$('[data-action="surprise"]'),token=request;button.disabled=true;try{const item=await window.zero.surprise();if(token!==request)return;titles.set(key(item),item);await details(item);}catch(error){toast(error.message);}finally{button.disabled=false;}}
async function renderCategories(){const token=++request;busy();try{const data=await api('/genre/'+genreType+'/list');if(token!==request)return;$('#content').innerHTML=`<div class="section-head"><h2>Find your kind of story</h2><div class="type-switch"><button data-genre-type="movie" class="${genreType==='movie'?'selected':''}">Movies</button><button data-genre-type="tv" class="${genreType==='tv'?'selected':''}">TV series</button></div></div><div class="genre-grid">${[...(data.genres||[]).filter(x=>Number.isSafeInteger(x.id)&&x.id>0),{id:-16,name:"Anime"},{id:-101,name:"Japanese titles"},{id:-102,name:"Korean titles"},{id:-103,name:"Filipino titles"},{id:-104,name:"French titles"},{id:-105,name:"Spanish titles"},{id:-106,name:"Hindi titles"}].sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<button data-genre="${x.id}" data-name="${escape(x.name)}"><span class="genre-caption">${escape(x.name)}<span>Explore →</span></span></button>`).join('')}</div>`;status('Categories from TMDB');for(const node of document.querySelectorAll('[data-genre]'))genreArtwork(node,genreType,Number(node.dataset.genre),token);}catch(error){if(token===request){$('#content').innerHTML=empty('Categories unavailable.',error.message);status(error.message);}}}
function applyTheme(){window.zeroLayouts?.apply(state.settings.uiLayout);const theme=state.themes?.[state.settings.theme]||state.themes?.dark;document.documentElement.dataset.theme=state.settings.theme||'dark';if(theme)for(const [name,value]of Object.entries(theme))if(name!=='name')document.documentElement.style.setProperty('--'+(name==='accent'?'mint':name),value);document.documentElement.dataset.animations=String(state.settings.uiAnimations!==false);const button=$('[data-action="toggle-theme"]');button.textContent=state.settings.theme==='light'?'☾':'☀';button.title='Switch light and Default theme';}
function art(path,size='w185'){return /^\/[A-Za-z\d_.-]+$/.test(path||'')?`https://image.tmdb.org/t/p/${size}${path}`:'';}
function normalize(raw,type){type=type||raw.media_type;if(!['movie','tv'].includes(type)||raw.adult||!Number.isSafeInteger(Number(raw.id))||Number(raw.id)<1)return null;const item={id:Number(raw.id),type,title:raw.title||raw.name||'Untitled',overview:raw.overview||'',poster:art(raw.poster_path,state?.settings?.artQuality==='saver'?'w342':'w500'),backdrop:art(raw.backdrop_path,state?.settings?.performanceMode?'w500':'w1280'),date:raw.release_date||raw.first_air_date||'',popularity:Number(raw.popularity)||0,rating:Number(raw.vote_average)||0,voteCount:Number(raw.vote_count)||0,genreIds:Array.isArray(raw.genre_ids)?raw.genre_ids:[],originalLanguage:raw.original_language||'',originCountry:Array.isArray(raw.origin_country)?raw.origin_country:[]};titles.set(key(item),item);return item;}
function list(raw,type){const hidden=new Set(state?.notInterested||[]);return (raw?.results||[]).map(row=>normalize(row,type)).filter(item=>item&&!hidden.has(key(item)));}
function key(item){return item.type+':'+item.id;}
async function api(path,params={},fresh=false){const id=path+JSON.stringify(params);if(!fresh&&cache.get(id)?.until>Date.now())return cache.get(id).data;const data=await window.zero.api(path,params);cache.set(id,{data,until:Date.now()+300000});while(cache.size>100)cache.delete(cache.keys().next().value);return data;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function status(message){$('#status').textContent=message;}
function busy(){window.zeroExperience?.stop();clearInterval(heroTimer);$('#content').innerHTML='<div class="skeleton" aria-label="Loading titles"></div>';status('Updating your catalog…');}
function empty(title,message){return `<div class="empty"><h2>${escape(title)}</h2><p>${escape(message)}</p><div class="actions" style="justify-content:center"><button data-action="settings">Settings</button><button data-action="refresh">Try again</button></div></div>`;}
function badge(item){return `<div class="badges"><span class="badge">${item.type==='tv'?'TV SERIES':'MOVIE'}</span>${item.date?`<span>${escape(item.date.slice(0,4))}</span>`:''}${item.rating?`<span class="rating">★ ${item.rating.toFixed(1)}</span>`:''}</div>`;}
function card(item,landscape=false){titles.set(key(item),item);const position=state.positions[key(item)],percent=Number(position?.percent)||0;const img=landscape||!['classic','flix'].includes(state.settings.uiLayout)?(item.backdrop||item.poster):item.poster;const rating=item.rating?' · <span class="thumb-rating">★ '+Number(item.rating).toFixed(1)+'</span>':'';const year=item.date?.slice(0,4)||'',badgeText=percent>=95?'WATCHED':percent>0?'IN PROGRESS':state.favorites.some(row=>key(row)===key(item))?'WATCHLIST':year===String(new Date().getFullYear())?'NEW':'';return `<button class="card ${landscape?'landscape':''}" data-detail="${key(item)}" data-card-key="${key(item)}" aria-label="Details for ${escape(item.title)}"><div class="card-art">${img?`<img loading="lazy" decoding="async" src="${escape(img)}" alt="${escape(item.title)}">`:'<div class="poster-empty">Z</div>'}${badgeText?`<span class="zero22-badge">${badgeText}</span>`:''}<div class="thumb-copy"><strong>${escape(item.title)}</strong><small>${year||'TBA'} · ${item.type==='tv'?'Series':'Movie'}${rating}</small></div></div>${landscape&&item.date?`<span class="badge">${escape(item.date)}</span>`:''}<span class="card-title">${escape(item.title)}</span><small>${year||'TBA'} · ${item.type==='tv'?'Series':'Movie'}${item.rating?' · ★ '+Number(item.rating).toFixed(1):''}</small>${percent>0&&percent<95?`<div class="progress"><i style="width:${Math.min(100,percent)}%"></i></div><small>${Math.round(percent)}% watched${item.type==='tv'?' · S'+position.season+' E'+position.episode:''}</small>`:''}</button>`;}
function row(label,items,landscape=false){return items.length?`<section class="row-section"><div class="section-head"><h3>${escape(label)}</h3><small>${items.length} picks</small></div><div class="cards">${items.map(item=>card(item,landscape)).join('')}</div></section>`:'';}
function continueItems(){return Object.values(state.positions).filter(item=>Number(item.timestamp)>0&&Number(item.percent)<95).sort((a,b)=>b.at-a.at);}
const carouselSourceLabels={top:"THIS WEEK'S TOP PICKS",watchlist:'FROM YOUR WATCHLIST',recommended:'RECOMMENDED MOVIES',popular:'POPULAR MOVIES',now:'NOW PLAYING',continue:'CONTINUE WATCHING'};
function heroPicks(){const source=state.settings.carouselSource||'top';let rows=source==='watchlist'?state.favorites:source==='recommended'?(homeData.recommended||[]):source==='popular'?(homeData.popular||[]):source==='now'?(homeData.now||[]):source==='continue'?continueItems():(homeData.trending||[]);const unique=new Map();for(const item of rows||[]){if(!item||!['movie','tv'].includes(item.type)||(!item.backdrop&&!item.poster))continue;unique.set(key(item),item);if(unique.size>=10)break;}if(!unique.size&&source!=='top')for(const item of homeData.trending||[]){if(item?.backdrop||item?.poster)unique.set(key(item),item);if(unique.size>=10)break;}return [...unique.values()].slice(0,10);}
function heroEyebrow(){return carouselSourceLabels[state.settings.carouselSource||'top']||carouselSourceLabels.top;}
function hero(){const picks=heroPicks();if(!picks.length)return '';heroIndex=((heroIndex%picks.length)+picks.length)%picks.length;const item=picks[heroIndex];return `<div class="hero" id="hero" data-featured="${key(item)}">${item.backdrop?`<img class="hero-art" src="${escape(item.backdrop)}" alt="">`:''}<div class="hero-shade"></div><div class="hero-content"><span class="eyebrow">${escape(heroEyebrow())}</span><div class="detail-heading"><div><h2>${escape(item.title)}</h2>${badge(item)}</div><div class="watch-actions"><button class="primary" data-play="${key(item)}">▶ Watch now</button>${sourceButton(item)}</div></div><p>${escape(item.overview||'A new story is waiting. Discover the details and find your next great watch.')}</p><div class="actions"><button class="primary" data-play="${key(item)}">▶ Watch now</button>${sourceButton(item)}<button data-detail="${key(item)}">More details</button><button data-favorite="${key(item)}">${state.favorites.some(row=>key(row)===key(item))?'✓ In watchlist':'+ My list'}</button></div><div class="hero-controls"><button data-action="hero-prev" aria-label="Previous featured title">‹</button>${picks.map((_,index)=>`<span class="dot ${index===heroIndex?'on':''}"></span>`).join('')}<button data-action="hero-next" aria-label="Next featured title">›</button></div></div><div class="ranked">${picks.map((pick,index)=>`<button data-hero="${index}"><strong>${String(index+1).padStart(2,'0')}</strong><span>${escape(pick.title)}</span></button>`).join('')}</div></div>`;}
function watchlistHome(){return state.favorites.length?row('Watchlist',state.favorites):'<section class="row-section home-watchlist"><h3>Watchlist</h3><p>Save movies and series from their details to see them here.</p></section>';}
function renderHero(){const old=$('#hero');if(!old)return;const picks=heroPicks();if(!picks.length){old.remove();return;}const item=picks[((heroIndex%picks.length)+picks.length)%picks.length];if(item&&old.dataset.featured===key(item))return;old.outerHTML=hero();bindHero();}
function bindHero(){const node=$('#hero');if(!node)return;if(!state.settings.performanceMode)window.zeroExperience?.hero();const picks=heroPicks();atmosphere(picks[((heroIndex%Math.max(1,picks.length))+Math.max(1,picks.length))%Math.max(1,picks.length)]);node.addEventListener('mouseenter',()=>heroPaused=true);node.addEventListener('mouseleave',()=>heroPaused=false);node.addEventListener('focusin',()=>heroPaused=true);node.addEventListener('focusout',()=>heroPaused=false);}
function providersHTML(rows){return `<section class="row-section"><div class="section-head"><h3>Explore your streaming favorites</h3><div class="type-switch"><button data-provider-type="movie" class="${providerType==='movie'?'selected':''}">Movies</button><button data-provider-type="tv" class="${providerType==='tv'?'selected':''}">TV series</button></div></div><div class="provider-row">${rows.map(row=>`<button class="provider" data-provider="${Number(row.provider_id)}" data-name="${escape(row.provider_name)}"><img loading="lazy" src="${escape(art(row.logo_path))}" alt=""><span>${escape(row.provider_name)}</span></button>`).join('')}</div><small style="color:var(--muted)">Availability in ${escape(state.settings.region)} by JustWatch · choose your playback source in Settings</small></section>`;}
async function providerRows(){const data=await api('/watch/providers/'+providerType,{watch_region:state.settings.region});const priority=['Netflix','Disney','Apple TV','Amazon Prime','HBO','Max','Paramount','Crunchyroll'];return (data.results||[]).filter(row=>Number(row.provider_id)>0&&art(row.logo_path)).sort((a,b)=>{const rank=name=>{const i=priority.findIndex(part=>name.includes(part));return i<0?99:i;};return rank(a.provider_name)-rank(b.provider_name);}).slice(0,14);}
const homePanels=[['clock','Clock'],['featured','Featured carousel'],['continue','Continue watching'],['upnext','Up next'],['because','Because you watched'],['watchlist','Watchlist'],['tonight',"Tonight's picks"],['hidden','Hidden gems'],['upcoming','Coming soon'],['providers','Streaming providers'],['recommended','Recommended movies'],['trending','Trending'],['popular','Popular movies'],['series','Series worth watching'],['now','Now playing'],['airing','Airing today'],['action','Action movies',28],['comedy','Comedy movies',35],['horror','Horror movies',27],['animation','Animation movies',16],['anime','Anime series',16],["adventure", "Adventure movies", 12],["crime", "Crime movies", 80],["documentary", "Documentaries", 99],["drama", "Drama movies", 18],["family", "Family movies", 10751],["fantasy", "Fantasy movies", 14],["history", "History movies", 36],["music", "Music movies", 10402],["mystery", "Mystery movies", 9648],["romance", "Romance movies", 10749],["scifi", "Science fiction movies", 878],["thriller", "Thriller movies", 53],["war", "War movies", 10752],["western", "Western movies", 37],["tvmovie", "TV movies", 10770]];
const enabledPanel=id=>(state.settings.homePanels||homePanels.slice(0,16).map(p=>p[0])).includes(id);
function homeOrder(){const known=new Set(homePanels.map(p=>p[0])),saved=Array.isArray(state.settings.homePanelOrder)?state.settings.homePanelOrder:[];return [...saved.filter(id=>known.has(id)),...homePanels.map(p=>p[0]).filter(id=>!saved.includes(id))];}
function panelSettings(defaults=false){const order=homeOrder();$('#home-panels').innerHTML=order.map(id=>{const i=homePanels.findIndex(p=>p[0]===id),label=homePanels[i]?.[1]||id;return `<label class="panel-toggle zero22-panel-row"><input type="checkbox" value="${id}" ${((defaults?i<16:enabledPanel(id)))?'checked':''}><span>${escape(label)}</span><button type="button" data-panel-move="up" data-panel-id="${id}" aria-label="Move up">↑</button><button type="button" data-panel-move="down" data-panel-id="${id}" aria-label="Move down">↓</button></label>`;}).join('');}
