function peopleHTML(){if(!peopleResults.length)return '';return '<section class="row-section"><div class="section-head"><h3>People</h3></div><div class="cards">'+peopleResults.slice(0,12).map(p=>`<button class="person-card" data-person="${Number(p.id)}" data-person-name="${escape(p.name)}">${p.profile_path?`<img loading="lazy" src="${escape(art(p.profile_path,'w185'))}" alt="">`:''}<strong>${escape(p.name)}</strong><small>${escape(p.known_for_department||'Person')}</small></button>`).join('')+'</div></section>'; }
async function personPage(id,name){const token=++detailRequest;$('#detail-body').innerHTML='<div class="settings-body"><h2>'+escape(name)+'</h2><p>Loading person profile…</p></div>';if(!$('#detail').open)$('#detail').showModal();try{const data=await api('/person/'+id,{append_to_response:'combined_credits'});if(token!==detailRequest)return;const credits=data.combined_credits||{},acting=(credits.cast||[]).map(x=>normalize(x)).filter(Boolean),directing=(credits.crew||[]).filter(x=>/Director|Creator|Writer/.test(x.job||'')).map(x=>normalize(x)).filter(Boolean),today=new Date().toLocaleDateString('en-CA'),upcoming=[...acting,...directing].filter(x=>x.date&&x.date>=today);$('#detail-body').innerHTML=`<div class="settings-body zero22-person">${data.profile_path?`<img class="person-profile" src="${escape(art(data.profile_path,'w500'))}" alt="">`:''}<h2>${escape(data.name||name)}</h2><p>${escape([data.known_for_department,data.birthday,data.place_of_birth].filter(Boolean).join(' · '))}</p><p>${escape(data.biography||'Biography unavailable.')}</p>${row('Known for',acting.slice(0,16))}${directing.length?row('Directing & creating',directing.slice(0,16)):''}${upcoming.length?row('Upcoming',upcoming.slice(0,16)):''}</div>`;}catch(error){toast(error.message);}}
async function collectionPage(id,name){try{const data=await api('/collection/'+id),items=(data.parts||[]).map(x=>normalize(x,'movie')).filter(Boolean);$('#detail-body').innerHTML='<div class="settings-body"><h2>'+escape(data.name||name)+'</h2><p>'+escape(data.overview||'Movie collection')+'</p>'+row('Collection',items)+'</div>';if(!$('#detail').open)$('#detail').showModal();}catch(error){toast(error.message);}}
function hiddenKey(item){return key(item)}
function moveHomePanel(id,delta){const order=homeOrder(),at=order.indexOf(id),to=Math.max(0,Math.min(order.length-1,at+delta));if(at<0||at===to)return;order.splice(at,1);order.splice(to,0,id);state.settings.homePanelOrder=order;}
function ensureZero22Settings(){if($('#zero22-settings'))return;const field=document.createElement('fieldset');field.id='zero22-settings';field.innerHTML='<legend>2.2 Discovery & Performance</legend><label>Local profile<select id="zero22-profile"></select></label><div class="actions"><button type="button" data-action="profile-add">New profile</button><button type="button" data-action="profile-switch">Switch profile</button><button type="button" data-action="profile-remove">Delete profile</button></div><label class="panel-toggle"><input type="checkbox" id="zero22-performance"> Performance mode</label><label>Artwork quality<select id="zero22-art"><option value="auto">Automatic</option><option value="high">High</option><option value="balanced">Balanced</option><option value="saver">Data Saver</option></select></label><label class="panel-toggle"><input type="checkbox" id="zero22-recovery"> Automatic source failure recovery</label><label class="panel-toggle"><input type="checkbox" id="zero22-best-source"> Prefer healthiest source on this PC</label><label class="panel-toggle"><input type="checkbox" id="zero22-autonext"> Autoplay next episode</label><label>Skip intro seconds<input id="zero22-intro" type="number" min="0" max="600"></label><label>Skip recap seconds<input id="zero22-recap" type="number" min="0" max="600"></label><div class="actions"><button type="button" data-action="mood">What should I watch?</button><button type="button" data-action="player-mini">Toggle mini player</button></div>';$('#preview-settings')?.insertAdjacentElement('afterend',field);}
