async function loadEpisodes(item,token,resume){try{const season=Number($('#season').value);$('#episode').innerHTML='<option>Loading…</option>';const data=await api('/tv/'+item.id+'/season/'+season);if(token!==detailRequest||!$('#detail').open||Number($('#season')?.value)!==season)return;$('#episode').innerHTML=(data.episodes||[]).filter(x=>x.episode_number>0).map(x=>`<option value="${Number(x.episode_number)}">E${Number(x.episode_number)} · ${escape(x.name)}${escape(episodeReminder(item,season,Number(x.episode_number)))}</option>`).join('');if(resume&&Array.from($('#episode').options).some(x=>Number(x.value)===resume))$('#episode').value=String(resume);}catch(error){toast(error.message);}}
async function play(item,ep){if(!item)return;window.zeroExperience?.stop();const source=sourceFor(item);try{status(source==='rawcast'?'RawCast uses your limited API quota · Resolving '+item.title+'…':'Opening '+item.title+'…');await window.zero.play(item,ep,source);oneTimeSources.delete(key(item));status('Now playing in this window · F11 full screen · Back closes menus or exits playback');}catch(error){toast(error.message);}}
async function settings(){window.zeroExperience?.stop();state=await window.zero.state();panelSettings();ensureZero22Settings();fillZero22Settings();$('#rawcastPlayback').checked=state.settings.rawcastPlayback===true;$('#playback-source option[value=rawcast]').hidden=state.settings.rawcastPlayback!==true;$('#theme').innerHTML=Object.entries(state.themes||{dark:{name:'Default'},light:{name:'Light'}}).map(([id,t])=>'<option value="'+id+'">'+escape(t.name)+'</option>').join('');for(const id of ['uiAnimations','focusInfo','focusTrailer','homepageTrailer'])$('#'+id).checked=state.settings[id]!==false;$('#previewDelay').value=String(state.settings.previewDelay||2000);$('#rawcast-key').value='';$('#rawcast-key').type='password';$('#rawcast-saved').textContent=state.rawcast?.saved?state.rawcast.masked:'No personal key saved';$('#rawcast-status').textContent=state.rawcast?.hasKey?'Configured · Test API to validate':'Not configured';window.zeroDownloads?.settingsUsage();window.zeroDownloads?.fillSettings();$('#api-key').value='';$('#region').value=state.settings.region;$('#carousel-source').value=state.settings.carouselSource||'top';$('#ui-layout').value=state.settings.uiLayout||'youtube';$('#theme').value=state.settings.theme||'dark';$('#playback-source').value=state.settings.source||'vidstuck';$('#gain').value=String(state.settings.gain);$('#key-state').textContent=state.hasKey?'A TMDB key is configured. Leave blank to keep it.':'No key configured. Add your TMDB v3 API key.';$('#settings-status').textContent='';$('#version').textContent='ZeroPlay for Windows · '+state.version;if(!$('#settings').open)$('#settings').showModal();}
async function change(action,value){state=await window.zero.change(action,value);applyTheme();return state;}
document.addEventListener('click',async event=>{const target=event.target.closest('button,[data-nav],.brand');if(!target)return;const action=target.dataset.action;try{
  if(target.dataset.person){await personPage(Number(target.dataset.person),target.dataset.personName||'Person');return;}if(target.dataset.collectionId){await collectionPage(Number(target.dataset.collectionId),target.dataset.collectionName||'Collection');return;}if(target.dataset.panelMove){moveHomePanel(target.dataset.panelId,target.dataset.panelMove==='up'?-1:1);panelSettings();return;}if(target.dataset.quick){await runQuick(target.dataset.quick);return;}  if(target.classList.contains('brand')){event.preventDefault();await navigate('Home');return;}
  if(target.dataset.favoriteChannel!==undefined){await window.zero.channelFavorite(category,Number(target.dataset.favoriteChannel));await renderPlaylist();return;}
  if(target.dataset.sportsEvent!==undefined){await window.zero.sportsPlay(target.dataset.sportsEvent,Number(target.dataset.sportsSource));return;}
  if(target.dataset.channel!==undefined){await window.zero.livePlay(category,Number(target.dataset.channel));return;}
  if(target.dataset.nav){await navigate(target.dataset.nav);return;}
  if(target.dataset.detail){const item=titles.get(target.dataset.detail);if(item)await details(item);return;}
  if(target.dataset.play){const item=titles.get(target.dataset.play);let ep;if(target.dataset.season&&target.dataset.episode)ep={season:Number(target.dataset.season),episode:Number(target.dataset.episode)};else if(item?.type==='tv'&&$('#detail').open&&activeDetail&&key(activeDetail)===target.dataset.play){const season=Number($('#season')?.value),episode=Number($('#episode')?.value);if(Number.isInteger(season)&&Number.isInteger(episode)&&episode>0)ep={season,episode};else{toast('Choose an episode first');return;}}await play(item,ep);return;}
  if(target.dataset.favorite||target.dataset.plan){const item=titles.get(target.dataset.favorite||target.dataset.plan);await change(target.dataset.favorite?'favorites':'planned',item);toast('Library updated');if($('#detail').open&&activeDetail)await details(activeDetail);else if(category==='Home')renderHero();else if(category==='Library')renderLibrary();return;}
  if(target.dataset.trailer){await window.zero.external(titles.get(target.dataset.trailer).trailer);return;}
  if(target.dataset.share){const item=titles.get(target.dataset.share);await window.zero.external('https://www.themoviedb.org/'+item.type+'/'+item.id);return;}
  if(target.dataset.library){libraryTab=target.dataset.library;renderLibrary();return;}
  if(target.dataset.query){category='Search';page=1;submittedQuery=target.dataset.query;$('#query').value=target.dataset.query;await change('search',target.dataset.query);await searchTitles();return;}
  if(target.dataset.removeQuery){await change('remove-search',target.dataset.removeQuery);category==='Library'?renderLibrary():searchTitles();return;}
  if(target.dataset.removeHistory){await change('remove-history',target.dataset.removeHistory);renderLibrary();return;}
  if(target.dataset.hero){heroIndex=Number(target.dataset.hero);renderHero();return;}
  if(target.dataset.source){pendingSource=target.dataset.source;$('#source-picker').close();const dialog=ensureSourceConfirm();$('#source-confirm-title').textContent='Use '+sourceName(pendingSource)+' for '+sourcePickerItem.title+'?';$('#source-confirm-copy').textContent='Keep this as the preferred source for this title only? Other movies and series will continue using VidStuck.';dialog.showModal();return;}
  if(action==='source-keep'){const saved=sourceOverrides();saved[key(sourcePickerItem)]=pendingSource;localStorage.setItem('zero-title-sources',JSON.stringify(saved));oneTimeSources.delete(key(sourcePickerItem));$('#source-confirm').close();toast('Saved for '+sourcePickerItem.title+' only');if($('#detail').open&&activeDetail)await details(activeDetail);else if(category==='Home')renderHero();return;}
  if(action==='source-once'){oneTimeSources.set(key(sourcePickerItem),pendingSource);$('#source-confirm').close();toast('Using '+sourceName(pendingSource)+' next time for this title');if($('#detail').open&&activeDetail)await details(activeDetail);else if(category==='Home')renderHero();return;}
  if(action==='source-cancel'){$('#source-confirm').close();return;}
  if(target.dataset.genreType){genreType=target.dataset.genreType;await renderCategories();return;}
  if(target.dataset.genre){if(Number(target.dataset.genre)===-16){await openAnime(genreType);return;}genreId=Number(target.dataset.genre);genreName=target.dataset.name;category='Genre';page=1;$('#heading').textContent=genreName+' · '+(genreType==='tv'?'TV series':'Movies');await browse();return;}
  if(target.dataset.providerType){providerType=target.dataset.providerType;const token=request;const rows=await providerRows();if(token===request&&$('#providers'))$('#providers').innerHTML=providersHTML(rows);return;}
  if(target.dataset.provider){providerId=Number(target.dataset.provider);providerName=target.dataset.name;await navigate('Provider');$('#heading').textContent=providerName+' · '+(providerType==='tv'?'TV series':'Movies');return;}
  if(action==='toggle-theme'){await change('settings',{...state.settings,theme:state.settings.theme==='light'?'dark':'light',source:state.settings.source||'vidstuck'});toast(state.settings.theme==='light'?'Light mode':'Night mode');}
  else if(action==='source')openSources(activeDetail||heroPicks()[heroIndex]);
  else if(action==='close-source')$('#source-picker').close();
  else if(action==='settings')await settings();
  else if(action==='clear-history'){if(!window.confirm('Clear watched history and all in-progress episode markers? Your watchlist, downloads and settings will be kept.'))return;await change('clear-history');toast('Watched history cleared');if(category==='Library')renderLibrary();}
  else if(action==='close'){$('#detail').close();++detailRequest;if(category==='Home')await renderHome();else observePaging();}
  else if(action==='restore-panels')panelSettings(true);
  else if(action==='reset-app'){if(!window.confirm('Reset ZeroPlay settings, watchlist, history, collections and API preferences to defaults? Downloaded media files will be kept.'))return;await change('reset');try{localStorage.clear();}catch{}$('#settings').close();toast('ZeroPlay reset to defaults');setTimeout(()=>location.reload(),250);}
  else if(action==='close-settings')$('#settings').close();
  else if(action==='hero-prev'||action==='hero-next'){const count=heroPicks().length;if(count){heroIndex+=(action==='hero-next'?1:count-1);renderHero();}}
  else if(action==='refresh-sports')await renderSports(true);
  else if(action==='refresh-playlist')await renderPlaylist(true);
  else if(action==='retry-more'){page++;await catalogPage(true);}
  else if(action==='anime')await openAnime('tv');
  else if(action==='anime-movies')await openAnime('movie');
  else if(action==='refresh'){if(category==='Live Sports'){await renderSports(true);return;}cache.clear();page=1;if(playlistTab()){await renderPlaylist(true);return;}if(category==='Home')await renderHome(true);else if(category==='Search')await searchTitles();else if(category==='Library')renderLibrary();else if(category==='Categories')await renderCategories();else await browse();}
  else if(action==='surprise')await surpriseMovie();
  else if(action==='mood')await moodDiscovery();
  else if(action==='profile-add')await addProfile();
  else if(action==='profile-switch')await switchProfile();
  else if(action==='profile-remove')await removeProfile();
  else if(action==='player-mini')await window.zero.playerMini();
  else if(action==='clear-searches'){await change('clear-searches');category==='Library'?renderLibrary():searchTitles();}
  else if(action==='clear-history'){await change('clear-history');renderLibrary();}
  else if(action==='collection'){const name=$('#collection-name')?.value.trim();if(!name){toast('Enter a collection name');return;}await change('collection',{name,item:activeDetail});toast('Collection updated');}
  else if(action==='save-settings'||action==='bundled-key'){await change('settings',{...state.settings,...Object.fromEntries(['uiAnimations','focusInfo','focusTrailer','homepageTrailer'].map(id=>[id,$('#'+id).checked])),rawcastPlayback:$('#rawcastPlayback').checked,previewDelay:Number($('#previewDelay').value),uiLayout:$('#ui-layout').value,carouselSource:$('#carousel-source').value,region:$('#region').value,theme:$('#theme').value,source:$('#playback-source').value,gain:Number($('#gain').value),homePanels:[...document.querySelectorAll('#home-panels input:checked')].map(n=>n.value),homePanelOrder:homeOrder(),performanceMode:$('#zero22-performance')?.checked===true,artQuality:$('#zero22-art')?.value||'auto',autoSourceRecovery:$('#zero22-recovery')?.checked===true,autoBestSource:$('#zero22-best-source')?.checked!==false,autoplayNext:$('#zero22-autonext')?.checked!==false,skipIntroSeconds:Number($('#zero22-intro')?.value||90),skipRecapSeconds:Number($('#zero22-recap')?.value||45),key:action==='bundled-key'?null:$('#api-key').value.trim()});cache.clear();$('#settings').close();toast('Settings saved');await navigate('Home',true);}
}catch(error){if($('#settings').open)$('#settings-status').textContent=error.message;else toast(error.message);}});
$('#search-form').addEventListener('submit',async event=>{event.preventDefault();try{submittedQuery=$('#query').value.trim();page=1;if(category==='Live Sports'){await renderSports();return;}if(playlistTab()){await renderPlaylist();return;}category='Search';for(const button of document.querySelectorAll('[data-nav]'))button.classList.toggle('active',button.dataset.nav==='Search');await change('search',submittedQuery);$('#heading').textContent='Find your next favorite.';await searchTitles();}catch(error){toast(error.message);}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&category==='LiveTV')renderPlaylist();else if(!document.hidden&&category==='Live Sports')renderSports();});
$('#detail').addEventListener('cancel',()=>{++detailRequest;if(category==='Home')renderHome();else observePaging();});
window.zero.onRefresh(async()=>{state=await window.zero.state();applyTheme();if(category==='Library')renderLibrary();else if(category==='Home')await renderHome();else observePaging();});
(async()=>{try{state=await window.zero.state();applyTheme();await navigate('Home');}catch(error){status(error.message);$('#content').innerHTML=empty('Could not start ZeroPlay.',error.message);}})();

async function genreArtwork(node,type,id,token){try{const data=await api('/discover/'+type,{...(id<=-101?{with_original_language:categoryLanguages[id]}:{with_genres:Math.abs(id)}),...(id===-16?{with_original_language:'ja'}:{}),page:1,sort_by:'popularity.desc'});if(token!==request||!node.isConnected)return;const example=(data.results||[]).find(r=>art(r.backdrop_path,'w1280')||art(r.poster_path,'w500'));if(!example)return;const img=document.createElement('img');img.className='genre-art';img.loading='lazy';img.alt='';img.src=art(example.backdrop_path,'w1280')||art(example.poster_path,'w500');node.prepend(img);}catch{}}

async function openAnime(type){genreType=type;genreId=16;genreName='Anime · '+(type==='tv'?'Series':'Movies');await navigate('Genre');}
async function renderSports(force=false){const token=++request;clearTimeout(liveTimer);if(!$('#sports-catalogue'))busy();const refresh=$('[data-action="refresh-sports"]');if(refresh){refresh.disabled=true;refresh.textContent='↻ Refreshing…';}status('Refreshing Live Sports…');try{const snapshot=await window.zero.sports(force);if(token!==request||category!=='Live Sports')return;const filter=submittedQuery.toLowerCase();const y=window.scrollY;$('#content').innerHTML='<div class="section-head"><h2>🏟 Live Sports</h2><button class="refresh-live" data-action="refresh-sports">↻ Refresh sports</button></div><p>Embedded players · catalogue auto-refreshes every hour</p>'+sortTools('sports',sportsSort,['Schedule','A–Z','Z–A'])+'<div id="sports-catalogue">'+[...snapshot.categories].sort((a,b)=>a.category.localeCompare(b.category)).map(c=>{const events=c.events.filter(e=>!filter||(c.category+' '+e.title).toLowerCase().includes(filter)).sort((a,b)=>sportsSort==='A–Z'?a.title.localeCompare(b.title):sportsSort==='Z–A'?b.title.localeCompare(a.title):(a.start||0)-(b.start||0));return events.length?'<h3>'+escape(c.category)+'</h3><div class="grid">'+events.map(e=>{const now=Date.now()/1000;const label=e.alwaysLive?'LIVE · 24/7':!e.start?'Schedule unavailable':(now>=e.start&&now<e.end?'LIVE · ':now>=e.end?'Ended · ':'Scheduled · ')+new Date(e.start*1000).toLocaleString();return '<article class="sports-card">'+(e.poster?'<img loading="lazy" src="'+escape(e.poster)+'" alt="">':'')+'<h3>'+escape(e.title)+'</h3><p>'+escape(label)+'</p>'+e.sources.map((s,i)=>'<button data-sports-event="'+escape(e.id)+'" data-sports-source="'+i+'">▶ '+escape(s.label)+'</button>').join('')+'</article>';}).join('')+'</div>':'';}).join('')+'</div>';status(snapshot.error||'Sports updated '+new Date(snapshot.updated).toLocaleTimeString());window.scrollTo?.(0,y);}catch(e){if(token===request){$('#content').innerHTML=empty('Live Sports unavailable',e.message)+'<button class="refresh-live" data-action="refresh-sports">↻ Retry sports</button>';status(e.message);}}finally{if(refresh?.isConnected){refresh.disabled=false;refresh.textContent='↻ Refresh sports';}if(category==='Live Sports')liveTimer=setTimeout(()=>{if(!document.hidden)renderSports(false);},3600000);}}

document.querySelector('#rawcastPlayback').addEventListener('change',event=>{document.querySelector('#playback-source option[value=rawcast]').hidden=!event.target.checked;document.querySelector('#rawcast-controls').hidden=!event.target.checked;if(!event.target.checked&&document.querySelector('#playback-source').value==='rawcast')document.querySelector('#playback-source').value='vidstuck';});

document.addEventListener('contextmenu',event=>{const card=event.target.closest?.('[data-card-key]');if(!card)return;const item=titles.get(card.dataset.cardKey);if(!item)return;event.preventDefault();openQuick(item,event.clientX,event.clientY);});
document.addEventListener('change',async event=>{const name=event.target.dataset.filter;if(!name)return;const type=category==='Series'?'tv':'movie';catalogFilters[type]=catalogFilters[type]||{};catalogFilters[type][name]=event.target.value;localStorage.setItem('zero-catalog-filters',JSON.stringify(catalogFilters));page=1;await catalogPage(false);});
document.addEventListener('click',async event=>{if(event.target.closest?.('[data-action="clear-filters"]')){const type=category==='Series'?'tv':'movie';catalogFilters[type]={};localStorage.setItem('zero-catalog-filters',JSON.stringify(catalogFilters));await catalogPage(false);}});
